import { renderHook } from '@testing-library/react-hooks';
import useProgressTracker from './useProgressTracker';

const hookParamsMockWithoutInitialStep = {
  stepQuantity: 5,
};

const hookParamsMockWithInitialStep = {
  initialStep: 2,
  ...hookParamsMockWithoutInitialStep,
};

describe('Progress Tracker Hook', () => {
  it('When I pass an initialStep for hook configuration the currentStep returned by hook must be the value of the property initialStep', () => {
    const { result } = renderHook(() => useProgressTracker(hookParamsMockWithInitialStep));
    expect(result.current.currentStep).toBe(2);
  });

  it("When I don't pass an initialStep for hook configuration the currentStep returned by hook must be 0", () => {
    const { result } = renderHook(() => useProgressTracker(hookParamsMockWithoutInitialStep));
    expect(result.current.currentStep).toBe(0);
  });

  it('When I use goTo hook function with a step number out of step range must be trigged a console warn', () => {
    jest.spyOn(console, 'warn').mockImplementation();
    const { result } = renderHook(() => useProgressTracker(hookParamsMockWithInitialStep));
    result.current.goTo(10);
    expect(console.warn).toHaveBeenCalledWith(
      expect.stringContaining('The next navigation step index not exist. Insert a valid index.')
    );
  });

  it('When I use goTo hook function with a step number into the step range the currentStep must be changed for the step index called on goTo function', async () => {
    const { result } = renderHook(() => useProgressTracker(hookParamsMockWithInitialStep));
    result.current.goTo(3);
    expect(result.current.currentStep).toBe(3);
  });

  it('When I use goToNext hook function with the intialStep 2 the currentStep must be changed to 3', async () => {
    const { result } = renderHook(() => useProgressTracker(hookParamsMockWithInitialStep));
    result.current.goToNext();
    expect(result.current.currentStep).toBe(3);
  });

  it('When I use goToPrevious hook function with the intialStep 2 the currentStep must be changed to 1', async () => {
    const { result } = renderHook(() => useProgressTracker(hookParamsMockWithInitialStep));
    result.current.goToPrevious();
    expect(result.current.currentStep).toBe(1);
  });

  it('When I use reset hook function with the intialStep 2 and the currentStep is 3, the currentStep must be changed to 2', async () => {
    const { result } = renderHook(() => useProgressTracker(hookParamsMockWithInitialStep));
    result.current.goTo(3);
    result.current.reset();
    expect(result.current.currentStep).toBe(2);
  });

  it('When I use reset hook function without initialStep and the currentStep is 3, the currentStep must be changed to 0', async () => {
    const { result } = renderHook(() => useProgressTracker(hookParamsMockWithoutInitialStep));
    result.current.goTo(3);
    result.current.reset();
    expect(result.current.currentStep).toBe(0);
  });
});
